-- Isolated local PostgreSQL only. Synthetic Storage metadata, not real files.
-- All documents, objects, policies and test helpers are rolled back.
begin;
create temporary table blog_test_results(label text primary key);
create function pg_temp.blog_assert(ok boolean,label text) returns void language plpgsql security definer set search_path=pg_catalog as $$
begin if ok is distinct from true then raise exception 'blog assertion failed: %',label; end if;
 insert into pg_temp.blog_test_results values(label); end $$;
create policy blog_test_broad_policy on storage.objects for all to public using(true) with check(true);
do $tests$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); w uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); q uuid:=gen_random_uuid(); t uuid:=gen_random_uuid();
 d jsonb; second_doc jsonb; photo1 jsonb; photo2 jsonb; r jsonb; saved jsonb; first_publication jsonb; second_publication jsonb; pub jsonb;
 original_token uuid; blog_token uuid; media_id text; path1 text; path2 text; op uuid:=gen_random_uuid(); pub_op uuid:=gen_random_uuid(); withdraw_op uuid:=gen_random_uuid(); n integer; cursor jsonb; page1 jsonb; page2 jsonb;
begin
 d:=jsonb_build_object('format','life-photo-post-v2','id',p::text,'revision',1,'title','익명 여행 글','status','saved','replaces',null,
  'createdAt','2026-10-17T00:00:00.000Z','updatedAt','2026-10-17T00:00:00.000Z',
  'ops',jsonb_build_array(jsonb_build_object('insert',E'한글 🌱 원문\n')),'photos','[]'::jsonb,'attachments','[]'::jsonb,'archived',false);
 perform pg_temp.blog_assert(haedo_blog_private.valid_document(d,p),'saved plain text document validates');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(d||'{"status":"draft"}',p),'draft upload is rejected');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(d||'{"private_extra":"blocked"}',p),'unknown document fields are rejected');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document((d-'attachments'-'archived')||'{"format":null}',p),'null format cannot bypass strict document validation');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(jsonb_set(d,'{ops}','[{"insert":"unsafe\n","attributes":{"link":"javascript:alert(1)"}}]'),p),'script links are rejected');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(jsonb_set(d,'{ops}','[{"insert":{"html":"<script>bad</script>"}}]'),p),'HTML embeds are rejected');
 perform pg_temp.blog_assert(haedo_blog_private.utf16('🌱')=2,'UTF16 length matches browser');
 photo1:=jsonb_build_object('id','local-photo-one','name','private-filename-one.png','type','image/png','width',4032,'height',3024,'size',5,'digest',repeat('a',64));
 photo2:=jsonb_build_object('id','local-photo-two','name','private-filename-two.jpg','type','image/jpeg','width',1200,'height',1800,'size',7,'digest',repeat('b',64));
 d:=jsonb_set(d,'{photos}',jsonb_build_array(photo1,photo2));
 d:=jsonb_set(d,'{ops}',jsonb_build_array(jsonb_build_object('insert',E'한글 🌱 원문\n'),
  jsonb_build_object('insert',jsonb_build_object('photo',jsonb_build_object('id','local-photo-one','caption',E'첫 사진\n설명','alt','첫 사진 대체 텍스트'))),
  jsonb_build_object('insert',jsonb_build_object('photo',jsonb_build_object('id','local-photo-two','caption','비공개로 남길 두 번째 사진','alt','두 번째 사진'))),jsonb_build_object('insert',E'끝\n')));
 perform pg_temp.blog_assert(haedo_blog_private.valid_document(d,p),'original photo metadata and exact captions validate');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(jsonb_set(d,'{photos,0,type}','null'),p),'null media type cannot bypass validation');
 perform pg_temp.blog_assert(not haedo_blog_private.valid_document(jsonb_set(d,'{photos,0,id}','null'),p),'null private photo ID cannot bypass validation');
 insert into storage.buckets(id,name,public) values('blog-test-unrelated','Unrelated fixture',false);
 insert into storage.objects(bucket_id,name,metadata) values('blog-test-unrelated','unrelated-original','{"size":9}');
 execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform pg_temp.blog_assert(public.life_blog_list()='[]','account starts with no blog posts');
 perform pg_temp.blog_assert((select count(*)=1 from storage.objects where bucket_id='blog-test-unrelated'),'new bucket guards preserve existing unrelated read policy');
 update storage.objects set metadata='{"size":10}' where bucket_id='blog-test-unrelated';
 perform pg_temp.blog_assert((select metadata->>'size'='10' from storage.objects where bucket_id='blog-test-unrelated'),'new bucket guards preserve unrelated write policy');
 r:=public.life_blog_prepare_asset(p,'local-photo-one',repeat('a',64),5,'image/png',4032,3024); path1:=r->>'path';
 perform pg_temp.blog_assert(r->>'bucket'='haedo-blog-originals' and r->'exists'='false','prepare gives private immutable path');
 perform pg_temp.blog_assert(left(path1,36)=a::text and position('private-filename' in path1)=0,'asset path has owner namespace without filename');
 begin perform public.life_blog_prepare_asset(p,'local-photo-one',repeat('a',64),6,'image/png',4032,3024); raise exception 'changed asset metadata accepted';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'same digest metadata cannot be replaced'); end;
 begin perform public.life_blog_save(w,p,0,op,d); raise exception 'missing upload accepted';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'missing originals block document commit'); end;
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('haedo-blog-originals',path1,a::text,'{"size":5,"mimetype":"image/png"}');
 r:=public.life_blog_prepare_asset(p,'local-photo-two',repeat('b',64),7,'image/jpeg',1200,1800); path2:=r->>'path';
 begin perform public.life_blog_save(w,p,0,op,d); raise exception 'partial upload accepted';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'partially uploaded document is never committed'); end;
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('haedo-blog-originals',path2,a::text,'{"size":7,"mimetype":"image/jpeg"}');
 perform pg_temp.blog_assert((public.life_blog_prepare_asset(p,'local-photo-one',repeat('a',64),5,'image/png',4032,3024)->>'exists')::boolean,'identical original can be reused');
 select count(*) into n from storage.objects where name in(path1,path2);
 perform pg_temp.blog_assert(n=2,'owner reads own originals');
 update storage.objects set metadata='{}' where name=path1;
 perform pg_temp.blog_assert((select metadata->>'size'='5' from storage.objects where name=path1),'original updates remain denied despite permissive existing policy');
 delete from storage.objects where name=path1;
 perform pg_temp.blog_assert((select count(*)=1 from storage.objects where name=path1),'original deletes remain denied despite permissive existing policy');
 r:=public.life_blog_save(w,p,0,op,d); saved:=r;
 perform pg_temp.blog_assert(r='{"status":"stored","revision":1}','complete original set permits private document CAS');
 perform pg_temp.blog_assert(public.life_blog_save(w,p,0,op,d)=saved,'lost acknowledgement reuses durable receipt');
 begin perform public.life_blog_save(w,p,0,op,d||'{"title":"changed"}'); raise exception 'receipt payload changed';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'operation payload mutation is rejected'); end;
 perform pg_temp.blog_assert(public.life_blog_save(w,p,0,gen_random_uuid(),d)='{"status":"conflict","revision":1}','stale private CAS preserves document');
 perform pg_temp.blog_assert(public.life_blog_read(p)->'data'=d,'private server round trip preserves full metadata and exact content');
 perform pg_temp.blog_assert(public.life_blog_read(p)->'assets'->'local-photo-one'->>'path'=path1,'private read includes owner-only original locator');
 begin perform public.life_blog_save(w,p,1,gen_random_uuid(),d-'attachments'-'archived'||'{"format":"life-photo-post-v1"}'); raise exception 'format downgrade accepted';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'legacy writer cannot erase v2 fields'); end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform pg_temp.blog_assert(public.life_blog_read(p) is null and public.life_blog_list()='[]','foreign account cannot discover private documents');
 perform pg_temp.blog_assert(public.life_blog_save(w,p,1,gen_random_uuid(),d)='{"status":"missing"}','foreign account gets no remote revision');
 select count(*) into n from storage.objects where name=path1;
 perform pg_temp.blog_assert(n=0,'foreign account cannot read originals despite broad existing policy');
 begin insert into storage.objects(bucket_id,name,metadata) values('haedo-blog-originals',path1||'bad','{}'); raise exception 'foreign upload accepted';
 exception when insufficient_privilege then perform pg_temp.blog_assert(true,'unprepared or foreign original upload denied'); end;
 begin perform public.life_blog_public_media(gen_random_uuid(),'unknown'); raise exception 'private locator RPC exposed';
 exception when insufficient_privilege then perform pg_temp.blog_assert(true,'authenticated client cannot invoke media locator RPC'); end;
 begin perform 1 from haedo_blog_private.posts; raise exception 'private table directly readable';
 exception when insufficient_privilege then perform pg_temp.blog_assert(true,'private tables cannot be queried directly'); end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 r:=public.life_blog_publish(p,1,pub_op,array['local-photo-one'],'{"name":"공개 작성자","intro":"직접 고른 소개"}',0);
 first_publication:=r; original_token:=(r->>'token')::uuid; blog_token:=(r->>'blogToken')::uuid;
 perform pg_temp.blog_assert(r->>'status'='stored' and r->'revision'='1','first explicit publication creates independent public revision');
 perform pg_temp.blog_assert(public.life_blog_publish(p,1,pub_op,array['local-photo-one'],'{"name":"공개 작성자","intro":"직접 고른 소개"}',0)=first_publication,'publication acknowledgement retry preserves exact token and revision');
 perform pg_temp.blog_assert((public.life_blog_read(p)->'publication'->>'active')::boolean,'owner publication state reports active');
 r:=public.life_blog_publish(p,1,gen_random_uuid(),array['local-photo-two'],'{"name":"다른 선택","intro":""}',0);
 perform pg_temp.blog_assert(r='{"status":"conflict","revision":1}','two devices on same private revision cannot overwrite each others publication selection');
 execute 'reset role';
 select count(*) into n from haedo_blog_private.posts where owner_id=a and id=p;
 perform pg_temp.blog_assert(n=1,'publication leaves private original in place');
 execute 'set local role anon'; perform set_config('request.jwt.claims','{}',true);
 pub:=public.life_blog_public_read(original_token);
 perform pg_temp.blog_assert(pub->'snapshot'->>'format'='life-blog-public-v1','anonymous public read returns strict detached snapshot');
 perform pg_temp.blog_assert(jsonb_array_length(pub->'snapshot'->'photos')=1,'only explicitly selected photo is public');
 media_id:=pub->'snapshot'->'photos'->0->>'id';
 perform pg_temp.blog_assert(media_id<>'local-photo-one' and pub->'snapshot'->'photos'->0 ? 'name'=false,'public photo IDs are remapped and private filenames omitted');
 perform pg_temp.blog_assert(position('local-photo-' in pub::text)=0 and position(p::text in pub::text)=0 and position(w::text in pub::text)=0,'public snapshot contains no private document photo or workspace IDs');
 perform pg_temp.blog_assert(position('비공개로 남길 두 번째 사진' in pub::text)=0,'unselected photo caption and alt are not published');
 perform pg_temp.blog_assert(pub->'snapshot'->'ops'->1->'insert'->'photo'->>'caption'=E'첫 사진\n설명','selected original caption is preserved');
 page1:=public.life_blog_public_list(blog_token,1,null);
 perform pg_temp.blog_assert(jsonb_array_length(page1->'posts')=1 and page1->'author'->>'name'='공개 작성자','anonymous list is scoped to opaque author token');
 perform pg_temp.blog_assert(jsonb_array_length(public.life_blog_public_list(gen_random_uuid())->'posts')=0,'unknown author token cannot enumerate global posts');
 select count(*) into n from storage.objects where name in(path1,path2);
 perform pg_temp.blog_assert(n=0,'anonymous direct original download remains denied after publication');
 begin perform public.life_blog_read(p); raise exception 'anonymous private read permitted';
 exception when insufficient_privilege then perform pg_temp.blog_assert(true,'anonymous cannot call private blog RPC'); end;
 begin perform public.life_blog_public_media(original_token,media_id); raise exception 'anonymous locator exposed';
 exception when insufficient_privilege then perform pg_temp.blog_assert(true,'anonymous cannot obtain raw original locator'); end;
 execute 'set local role service_role';
 r:=public.life_blog_public_media(original_token,media_id);
 perform pg_temp.blog_assert(r->>'path'=path1 and r->>'digest'=repeat('a',64),'server-only media resolver admits exact published photo');
 perform pg_temp.blog_assert(public.life_blog_public_media(original_token,'local-photo-two') is null,'private or unselected photo ID cannot resolve publicly');
 execute 'set local role authenticated'; perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 r:=public.life_blog_publish(p,1,gen_random_uuid(),null,'{"name":"공개 작성자","intro":"갱신 소개"}',1);
 second_publication:=r;
 perform pg_temp.blog_assert(r->>'token'=original_token::text and r->'revision'='2','active publication update retains URL with fresh CAS revision');
 perform pg_temp.blog_assert(jsonb_array_length(public.life_blog_public_read(original_token)->'snapshot'->'photos')=0,'null photo selection defaults to no public photos');
 perform pg_temp.blog_assert(public.life_blog_unpublish(p,1,gen_random_uuid())='{"status":"conflict","revision":2}','stale withdrawal cannot erase newer publication');
 r:=public.life_blog_unpublish(p,2,withdraw_op);
 perform pg_temp.blog_assert(r='{"status":"stored","revision":3}','withdrawal advances independent publication revision');
 perform pg_temp.blog_assert(public.life_blog_unpublish(p,2,withdraw_op)=r,'withdrawal acknowledgement retry preserves exact result');
 r:=public.life_blog_read(p)->'publication';
 perform pg_temp.blog_assert(r->'active'='false' and r->'revision'='3' and r->>'token'=original_token::text,'inactive owner metadata retains token and revision');
 perform pg_temp.blog_assert(public.life_blog_public_read(original_token) is null,'withdrawn public token no longer resolves');
 page1:=public.life_blog_public_list(blog_token);
 perform pg_temp.blog_assert(page1->'posts'='[]' and page1->'author'='{"name":"","intro":""}','withdrawing final post also hides profile introduction');
 perform pg_temp.blog_assert(public.life_blog_publish(p,1,gen_random_uuid(),'{}','{"name":"","intro":""}',2)='{"status":"conflict","revision":3}','late publication cannot resurrect withdrawn selection');
 r:=public.life_blog_publish(p,1,gen_random_uuid(),array['local-photo-two'],'{"name":"작성자","intro":"재게시"}',3);
 perform pg_temp.blog_assert(r->>'token'<>original_token::text and r->>'blogToken'=blog_token::text and r->'revision'='4','republishing gets new post URL and stable author URL');
 perform pg_temp.blog_assert(public.life_blog_public_read(original_token) is null,'republishing does not revive the revoked URL');
 second_doc:=d||jsonb_build_object('id',t::text,'title','','ops',jsonb_build_array(d->'ops'->1,jsonb_build_object('insert',E'\n')));
 for pub in select * from jsonb_array_elements(second_doc->'photos') loop
  r:=public.life_blog_prepare_asset(t,pub->>'id',pub->>'digest',(pub->>'size')::bigint,pub->>'type',(pub->>'width')::integer,(pub->>'height')::integer);
  insert into storage.objects(bucket_id,name,owner_id,metadata) values('haedo-blog-originals',r->>'path',a::text,jsonb_build_object('size',pub->'size','mimetype',pub->'type'));
 end loop;
 perform public.life_blog_save(w,t,0,gen_random_uuid(),second_doc);
 begin perform public.life_blog_publish(t,1,gen_random_uuid(),array['local-photo-two'],'{"name":"","intro":""}',0); raise exception 'unreferenced photo published';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'unreferenced original metadata cannot become a public photo'); end;
 begin perform public.life_blog_publish(t,1,gen_random_uuid(),'{}','{"name":"","intro":""}',0); raise exception 'empty selection published';
 exception when invalid_parameter_value then perform pg_temp.blog_assert(true,'photo-only document with no selected photo cannot publish an empty post'); end;
 second_doc:=d||jsonb_build_object('id',q::text,'photos','[]'::jsonb,'ops',jsonb_build_array(jsonb_build_object('insert',E'두 번째 글\n')));
 perform public.life_blog_save(w,q,0,gen_random_uuid(),second_doc);
 perform public.life_blog_publish(q,1,gen_random_uuid(),'{}','{"name":"작성자","intro":"소개"}',0);
 execute 'reset role';
 update haedo_blog_private.publications set updated_at='2026-10-17T12:00:00Z' where owner_id=a;
 execute 'set local role anon'; perform set_config('request.jwt.claims','{}',true);
 page1:=public.life_blog_public_list(blog_token,1,null); cursor:=page1->'nextCursor';
 page2:=public.life_blog_public_list(blog_token,1,cursor);
 perform pg_temp.blog_assert(jsonb_array_length(page2->'posts')=1 and page1->'posts'->0->>'token'<>page2->'posts'->0->>'token','timestamp ties paginate by token without omission');
 execute 'reset role';
end $tests$;
select jsonb_build_object('passed',count(*),'failures',0,'scope','isolated PostgreSQL roles/RLS/CAS/Storage metadata') as result from blog_test_results;
rollback;
